#define main historical_main
#include "../tissue-cuda/main.cu"
#undef main
#include <vector>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;const int dim=8,nnt=512,capacity=32768;std::vector<int>points(3*capacity,0);std::vector<float>g(2*capacity),b(2*capacity),prev(capacity,0),qt(capacity,0);for(int i=0;i<nnt;i++){points[i]=i%dim;points[nnt+i]=(i/dim)%dim;points[2*nnt+i]=i/(dim*dim);prev[i]=float(i%9)/8;qt[i]=float(i%13-6)/16;}for(int i=0;i<2*capacity;i++){g[i]=float(i%17+1)/32;b[i]=float(i%11+1)/64;}std::vector<std::vector<float>>cpu(2,std::vector<float>(capacity,0));int*dp;float*dg,*db,*dprev,*dqt,*dc[2];CK(cudaMalloc(&dp,points.size()*sizeof(int)));CK(cudaMalloc(&dg,g.size()*4));CK(cudaMalloc(&db,b.size()*4));CK(cudaMalloc(&dprev,capacity*4));CK(cudaMalloc(&dqt,capacity*4));CK(cudaMemcpy(dp,points.data(),points.size()*sizeof(int),cudaMemcpyHostToDevice));CK(cudaMemcpy(dg,g.data(),g.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(db,b.data(),b.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dprev,prev.data(),capacity*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dqt,qt.data(),capacity*4,cudaMemcpyHostToDevice));for(int s=0;s<2;s++){reference(points.data(),g.data(),b.data(),cpu[s].data(),prev.data(),qt.data(),nnt,capacity,1,s+1);CK(cudaMalloc(&dc[s],capacity*4));CK(cudaMemset(dc[s],0,capacity*4));tissue<<<2,256>>>(dp,dg,db,dc[s],dprev,dqt,nnt,capacity,1,s+1);}CK(cudaDeviceSynchronize());bool allok=true;
for(int trial=1;trial<=5;trial++){double seconds=0,ma=0;std::vector<float>out;bool ok=true;for(int s=0;s<2;s++){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)tissue<<<2,256>>>(dp,dg,db,dc[s],dprev,dqt,nnt,capacity,1,s+1);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<float>got(capacity);CK(cudaMemcpy(got.data(),dc[s],capacity*4,cudaMemcpyDeviceToHost));for(int i=0;i<capacity;i++){ma=fmax(ma,fabs(got[i]-cpu[s][i]));ok&=std::isfinite(got[i])&&got[i]==cpu[s][i]&&(i<nnt||got[i]==0);}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"tissue_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum_two_species_complete_nonlocal_tissue_solute_operator_native_step1\",\"jit_excluded\":true,\"internal_repeats\":%d,\"written_output_values\":1024,\"unchanged_zero_tail_values\":64512,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,repeat,file,out.size());}CK(cudaFree(dp));CK(cudaFree(dg));CK(cudaFree(db));CK(cudaFree(dprev));CK(cudaFree(dqt));for(auto*p:dc)CK(cudaFree(p));puts(allok?"PASS":"FAIL");return allok?0:1;}
